#include <vector>
#include <unordered_map>
#include <set>

class Solution {
public:
    std::vector<int> avoidFlood(std::vector<int>& rains) {
        int n = rains.size();
        std::vector<int> ans(n, 1);
        std::unordered_map<int, int> full;
        std::set<int> dryDays;
        for (int i = 0; i < n; ++i) {
            int lake = rains[i];
            if (lake == 0) {
                dryDays.insert(i);
            } else {
                ans[i] = -1;
                if (full.count(lake)) {
                    int prevDay = full[lake];
                    auto it = dryDays.upper_bound(prevDay);
                    if (it == dryDays.end()) return {};
                    ans[*it] = lake;
                    dryDays.erase(it);
                }
                full[lake] = i;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] avoidFlood(int[] rains) {
        int n = rains.length;
        int[] ans = new int[n];
        Arrays.fill(ans, 1);
        Map<Integer, Integer> full = new HashMap<>();
        TreeSet<Integer> dryDays = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            int lake = rains[i];
            if (lake == 0) {
                dryDays.add(i);
            } else {
                ans[i] = -1;
                if (full.containsKey(lake)) {
                    int prevDay = full.get(lake);
                    Integer dryDay = dryDays.higher(prevDay);
                    if (dryDay == null) return new int[0];
                    ans[dryDay] = lake;
                    dryDays.remove(dryDay);
                }
                full.put(lake, i);
            }
        }
        return ans;
    }
}

var avoidFlood = function(rains) {
    const n = rains.length;
    const ans = new Array(n).fill(1);
    const full = new Map();
    const dryDays = [];
    for (let i = 0; i < n; i++) {
        const lake = rains[i];
        if (lake === 0) {
            dryDays.push(i);
        } else {
            ans[i] = -1;
            if (full.has(lake)) {
                const prev = full.get(lake);
                let idx = -1;
                for (let j = 0; j < dryDays.length; j++) {
                    if (dryDays[j] > prev) {
                        idx = j;
                        break;
                    }
                }
                if (idx === -1) return [];
                const day = dryDays.splice(idx, 1)[0];
                ans[day] = lake;
            }
            full.set(lake, i);
        }
    }
    return ans;
};
